create table RB_CLIENT_ACCT (BASE_ACCT_NO VARCHAR(50) not null  ,CLIENT_NO VARCHAR(22) not null  ,CUST_INTERNAL_KEY INT null  ,CLIENT_TYPE VARCHAR(3) null  ,ACCT_DOMAIN VARCHAR(10) null  ,IS_CORP_SETTLE_CARD VARCHAR(1) null  ,CARD_PB_UNION_FLAG VARCHAR(1) null  ,DOC_CLASS VARCHAR(3) null  ,DOC_TYPE VARCHAR(4) null  ,VOUCHER_NO VARCHAR(60) null  ,CLIENT_VOUCHER_STATUS VARCHAR(3) null  ,WITHDRAWAL_TYPE VARCHAR(1) null  ,CLIENT_ACCT_STATUS VARCHAR(1) null  ,ACCT_OPEN_DATE TIMESTAMP(3) null  ,ACCT_BRANCH VARCHAR(30) null  ,CLOSE_BRANCH VARCHAR(30) null  ,CREATE_DATE TIMESTAMP(3) null  ,UPDATE_DATE TIMESTAMP(3) null  ,CREATE_USER_ID VARCHAR(30) null  ,UPDATE_USER_ID VARCHAR(30) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  , primary key(BASE_ACCT_NO,CLIENT_NO));